import{_ as s,c as a,a as e,o as p}from"./app-B9IyngIV.js";const t={};function l(c,n){return p(),a("div",null,[...n[0]||(n[0]=[e(`<h1 id="多租户多时区解决方案" tabindex="-1"><a class="header-anchor" href="#多租户多时区解决方案"><span>多租户多时区解决方案</span></a></h1><div style="background:#f8f9fa;padding:12px 16px;border-left:3px solid #4CAF50;margin-bottom:16px;border-radius:0 4px 4px 0;font-size:0.9rem;"><div style="display:flex;align-items:center;gap:30px;flex-wrap:wrap;"><div style="display:flex;align-items:center;gap:8px;"><span style="color:#666;">📅</span><span>2025-04-03</span></div><div style="display:flex;align-items:center;gap:8px;"><span style="color:#666;">✍️</span><span>Jixer</span></div></div></div><h2 id="背景" tabindex="-1"><a class="header-anchor" href="#背景"><span>背景</span></a></h2><p>项目中需要多个租户，每个租户所在的国家不同，所选用的时区也不同，相同的标准时间不同租户需要显示不同的时间，本文实现了多租户多时区的一套方案</p><h2 id="介绍" tabindex="-1"><a class="header-anchor" href="#介绍"><span>介绍</span></a></h2><p><strong>GMT</strong>：格林尼治标准时间，基于地球自转（天文观测）</p><p><strong>UTC</strong>：全球统一的时间标准，主要目的是提供一个全球通用的时间标准，避免不同地区时间差异带来的混乱</p><h2 id="实现流程" tabindex="-1"><a class="header-anchor" href="#实现流程"><span>实现流程</span></a></h2><h3 id="时区转化过程流程图" tabindex="-1"><a class="header-anchor" href="#时区转化过程流程图"><span>时区转化过程流程图</span></a></h3><p><img src="" alt=""><img src="https://gitee.com/lijunxi666/picture-bed/raw/master/zone/zone.png" alt=""><img src="" alt=""></p><ul><li>客户前端选择时间 A，时间 A 是个时区时间，前端将时间 A 转为 UTC 标准时间（UTC + 0）传入后端</li><li>后端用 Date 类型接收，存放在数据库中。回显的时间直接将 Date 数据返回给前端</li><li>前端收到 UTC + 0 时间数据，会先将标准时间转为租户时区时间再展示</li></ul><p>这样做的更改考虑到了系统很多地方都用到了 Date 类型，若是从后端下手对时间进行转换改造，改动的点很多。相反若是对前端改造，只需对公共的时间组件进行修改</p><h3 id="定时任务注解改造" tabindex="-1"><a class="header-anchor" href="#定时任务注解改造"><span>定时任务注解改造</span></a></h3><p>系统中的 <code>@Scheduled</code> 定时任务注解提供了 cron 表达式和时区两个参数，但是不同的租户的定时任务的时区不同，并且租户的时区参数可能会变化，所以原版的 <code>@Scheduled</code> 已经不能满足现在的需求</p><p>自定义注解 <code>@CustomScheduled</code>，包含租户 code 和 cron 两个参数</p><div class="language-java line-numbers-mode" data-highlighter="prismjs" data-ext="java"><pre><code><span class="line"><span class="token annotation punctuation">@Target</span><span class="token punctuation">(</span><span class="token class-name">ElementType</span><span class="token punctuation">.</span><span class="token constant">METHOD</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token annotation punctuation">@Retention</span><span class="token punctuation">(</span><span class="token class-name">RetentionPolicy</span><span class="token punctuation">.</span><span class="token constant">RUNTIME</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token annotation punctuation">@interface</span> <span class="token class-name">CustomScheduled</span> <span class="token punctuation">{</span></span>
<span class="line"></span>
<span class="line">    <span class="token class-name">String</span> <span class="token function">tenantCode</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">    <span class="token class-name">String</span> <span class="token function">cron</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>在项目启动的时候，扫描所有的 bean 中的所有方法，找到带有 <code>@CustomScheduled</code> 的注解的方法，根据租户 code 获取当前的时区，动态添加定时任务</p><div class="language-java line-numbers-mode" data-highlighter="prismjs" data-ext="java"><pre><code><span class="line"><span class="token annotation punctuation">@Component</span></span>
<span class="line"><span class="token keyword">class</span> <span class="token class-name">InitScheduled</span> <span class="token keyword">implements</span> <span class="token class-name">CommandLineRunner</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token annotation punctuation">@Autowired</span></span>
<span class="line">    <span class="token keyword">private</span> <span class="token class-name">ScheduledTaskRegistrar</span> taskRegistrar</span>
<span class="line"></span>
<span class="line">    <span class="token annotation punctuation">@Override</span></span>
<span class="line">    <span class="token keyword">void</span> <span class="token function">run</span><span class="token punctuation">(</span><span class="token class-name">String</span><span class="token punctuation">.</span><span class="token punctuation">.</span><span class="token punctuation">.</span> args<span class="token punctuation">)</span> <span class="token keyword">throws</span> <span class="token class-name">Exception</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token function">doScheduled</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">  </span>
<span class="line">    <span class="token keyword">private</span> <span class="token keyword">void</span> <span class="token function">doScheduled</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token comment">// 扫描所有的bean</span></span>
<span class="line">        <span class="token class-name">Bean</span><span class="token punctuation">.</span><span class="token function">getBeansOfType</span><span class="token punctuation">(</span><span class="token class-name">Object</span><span class="token punctuation">)</span><span class="token operator">?</span><span class="token punctuation">.</span><span class="token function">values</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">?</span><span class="token punctuation">.</span>each <span class="token punctuation">{</span> bean <span class="token operator">-&gt;</span></span>
<span class="line">            <span class="token comment">// 扫描bean中的所有方法</span></span>
<span class="line">            bean<span class="token punctuation">.</span><span class="token function">getClass</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">getDeclaredMethods</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span>each <span class="token punctuation">{</span> method <span class="token operator">-&gt;</span></span>
<span class="line">                <span class="token keyword">if</span> <span class="token punctuation">(</span>method<span class="token punctuation">.</span><span class="token function">isAnnotationPresent</span><span class="token punctuation">(</span><span class="token class-name">CustomScheduled</span><span class="token punctuation">.</span><span class="token keyword">class</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">                    <span class="token class-name">CustomScheduled</span> scheduled <span class="token operator">=</span> method<span class="token punctuation">.</span><span class="token function">getAnnotation</span><span class="token punctuation">(</span><span class="token class-name">CustomScheduled</span><span class="token punctuation">)</span></span>
<span class="line">		    <span class="token comment">// 获取租户的时区，这里模拟</span></span>
<span class="line">		    <span class="token class-name">String</span> zoneId <span class="token operator">=</span> <span class="token string">&quot;UTC&quot;</span></span>
<span class="line">                    <span class="token class-name">Runnable</span> task <span class="token operator">=</span> <span class="token punctuation">{</span></span>
<span class="line">                        <span class="token keyword">try</span> <span class="token punctuation">{</span></span>
<span class="line">                            method<span class="token punctuation">.</span><span class="token function">invoke</span><span class="token punctuation">(</span>bean<span class="token punctuation">)</span></span>
<span class="line">                        <span class="token punctuation">}</span> <span class="token keyword">catch</span> <span class="token punctuation">(</span><span class="token class-name">Exception</span> e<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">                            <span class="token keyword">throw</span> <span class="token keyword">new</span> <span class="token class-name">RuntimeException</span><span class="token punctuation">(</span><span class="token string">&quot;Failed to execute tenant scheduled task&quot;</span><span class="token punctuation">,</span> e<span class="token punctuation">)</span></span>
<span class="line">                        <span class="token punctuation">}</span></span>
<span class="line">                    <span class="token punctuation">}</span></span>
<span class="line">                    <span class="token comment">// 时区</span></span>
<span class="line">                    <span class="token class-name">TimeZone</span> timeZone <span class="token operator">=</span> <span class="token class-name">TimeZone</span><span class="token punctuation">.</span><span class="token function">getTimeZone</span><span class="token punctuation">(</span>zoneId<span class="token punctuation">)</span></span>
<span class="line">                    <span class="token class-name">CronTrigger</span> trigger <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">CronTrigger</span><span class="token punctuation">(</span>scheduled<span class="token punctuation">.</span><span class="token function">cron</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span> timeZone<span class="token punctuation">)</span></span>
<span class="line">                    <span class="token comment">// 动态添加定时任务</span></span>
<span class="line">                    taskRegistrar<span class="token punctuation">.</span><span class="token function">scheduleCronTask</span><span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token class-name">CronTask</span><span class="token punctuation">(</span>task<span class="token punctuation">,</span> trigger<span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">                <span class="token punctuation">}</span></span>
<span class="line">            <span class="token punctuation">}</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>优化点：若租户的时区发生变化，只能通过重启项目才能解决</p><p>解决办法：当租户时区变化，动态的销毁租户原先的定时任务，创建新的定时任务</p>`,20)])])}const i=s(t,[["render",l]]),u=JSON.parse('{"path":"/java/%E5%A4%9A%E7%A7%9F%E6%88%B7%E5%A4%9A%E6%97%B6%E5%8C%BA%E8%A7%A3%E5%86%B3%E6%96%B9%E6%A1%88.html","title":"多租户多时区解决方案","lang":"en-US","frontmatter":{},"headers":[{"level":2,"title":"背景","slug":"背景","link":"#背景","children":[]},{"level":2,"title":"介绍","slug":"介绍","link":"#介绍","children":[]},{"level":2,"title":"实现流程","slug":"实现流程","link":"#实现流程","children":[{"level":3,"title":"时区转化过程流程图","slug":"时区转化过程流程图","link":"#时区转化过程流程图","children":[]},{"level":3,"title":"定时任务注解改造","slug":"定时任务注解改造","link":"#定时任务注解改造","children":[]}]}],"git":{},"filePathRelative":"java/多租户多时区解决方案.md"}');export{i as comp,u as data};
